import{_ as s,o as a,c as o,a0 as c}from"./chunks/framework.Bb-2yHh0.js";const d="/xv6-book-zh/assets/x86_translation.BldIWLtg.png",n="/xv6-book-zh/assets/x86_seg.DZAiQGsI.png",g=JSON.parse('{"title":"附录 B 引导加载器","description":"","frontmatter":{"title":"附录 B 引导加载器","outline":[2,3]},"headers":[],"relativePath":"appB.md","filePath":"appB.md"}'),p={name:"appB.md"};function i(l,e,t,r,h,x){return a(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="附录-b-引导加载器" tabindex="-1">附录 B　引导加载器 <a class="header-anchor" href="#附录-b-引导加载器" aria-label="Permalink to &quot;附录 B　引导加载器&quot;">​</a></h1><p>x86 PC 启动时，开始执行一个称为 BIOS（基本输入/输出系统）的程序，它存放在主板上的非易失性存储器中。BIOS 的工作是准备好硬件，然后把控制权转交给操作系统。具体地说，它把控制权转交给从引导扇区（引导磁盘的第一个 512 字节扇区）加载的代码。引导扇区包含引导加载器：把内核装入内存的指令。BIOS 把引导扇区加载到内存地址 <code>0x7c00</code>，然后跳转（设置处理器的 <code>%ip</code>）到该地址。引导加载器开始执行时，处理器正在模拟 Intel 8088，而加载器的任务是把处理器置于更现代的运行模式，从磁盘把 xv6 内核装入内存，然后把控制权转交给内核。xv6 的引导加载器由两个源文件组成，一个用 16 位和 32 位 x86 汇编的混合编写（<code>bootasm.S</code>），一个用 C 编写（<code>bootmain.c</code>）。</p><h2 id="appB-s1" tabindex="-1">代码：汇编引导程序 <a class="header-anchor" href="#appB-s1" aria-label="Permalink to &quot;代码：汇编引导程序 {#appB-s1}&quot;">​</a></h2><p>引导加载器的第一条指令是 <code>cli</code> <span class="ln">(9112)</span>，它禁用处理器中断。中断是硬件设备调用称为中断处理程序的操作系统函数的一种方式。BIOS 是一个微小的操作系统，它可能在初始化硬件的过程中设置了自己的中断处理程序。但 BIOS 已经不再运行——现在运行的是引导加载器——因此再处理来自硬件设备的中断既不合适也不安全。当 xv6 准备好时（在 <a href="./ch3">第 3 章</a> 中），它会重新启用中断。</p><p>处理器处于<em>实模式</em>，在这种模式下它模拟 Intel 8088。实模式有八个 16 位通用寄存器，但处理器向内存发送 20 位地址。段寄存器 <code>%cs</code>、<code>%ds</code>、<code>%es</code> 和 <code>%ss</code> 提供从 16 位寄存器生成 20 位内存地址所需的额外位。当程序引用一个内存地址时，处理器自动加上某个段寄存器值的 16 倍；这些寄存器是 16 位宽。使用哪个段寄存器通常隐含在内存引用的类型中：取指令使用 <code>%cs</code>，数据读写使用 <code>%ds</code>，栈读写使用 <code>%ss</code>。</p><figure class="xv6-fig" id="fig-x86_translation"><img src="'+d+'" alt="逻辑地址、线性地址与物理地址之间的关系。" loading="lazy"><figcaption><span class="fig-no">图 B-1</span>逻辑地址、线性地址与物理地址之间的关系。</figcaption></figure><p>xv6 假定 x86 指令对其内存操作数使用虚拟地址，但 x86 指令实际使用的是<em>逻辑地址</em>（见 <a class="figref" href="#fig-x86_translation">图 B-1</a>）。逻辑地址由段选择子和偏移量组成，有时写作段:偏移。更常见的情况是段是隐含的，程序只直接操作偏移量。分段硬件执行上述转换以生成<em>线性地址</em>。如果分页硬件已启用（见 <a href="./ch2">第 2 章</a>），它把线性地址转换为物理地址；否则处理器把线性地址用作物理地址。</p><p>引导加载器不启用分页硬件；它使用的逻辑地址由分段硬件转换为线性地址，然后直接用作物理地址。xv6 配置分段硬件，使逻辑地址到线性地址的转换保持不变，因此两者总是相等。由于历史原因，我们用<em>虚拟地址</em>这个术语来指程序操作的地址；xv6 的虚拟地址与 x86 的逻辑地址相同，并且等于分段硬件把它映射到的线性地址。一旦启用分页，系统中唯一值得关注的地址映射就是线性地址到物理地址。</p><p>BIOS 不保证 <code>%ds</code>、<code>%es</code>、<code>%ss</code> 的内容，因此禁用中断之后的第一件事就是把 <code>%ax</code> 设为零，然后把这个零复制到 <code>%ds</code>、<code>%es</code> 和 <code>%ss</code> <span class="ln">(9115-9118)</span>。</p><p>一个虚拟的段:偏移可能产生 21 位物理地址，但 Intel 8088 只能寻址 20 位内存，因此它会丢弃最高位：<code>0xffff0</code>+<code>0xffff</code> = <code>0x10ffef</code>，但在 8088 上虚拟地址 <code>0xffff</code>:<code>0xffff</code> 指的是物理地址 <code>0x0ffef</code>。一些早期软件依赖硬件忽略第 21 位地址，因此当 Intel 推出物理地址超过 20 位的处理器时，IBM 提供了一个兼容性 hack，这成为 PC 兼容硬件的必备要求。如果键盘控制器输出端口的第二位为低，第 21 位物理地址就总被清零；如果为高，第 21 位就正常工作。引导加载器必须通过端口 0x64 和 0x60 对键盘控制器进行 I/O 操作，以启用第 21 位地址 <span class="ln">(9120-9136)</span>。</p><p>实模式的 16 位通用寄存器和段寄存器使程序很难使用超过 65,536 字节的内存，并且不可能使用超过 1 MB 的内存。自 80286 起的 x86 处理器具有<em>保护模式</em>，它允许物理地址拥有多得多的位；自 80386 起还有一种“32 位”模式，使寄存器、虚拟地址和大多数整数运算都以 32 位而非 16 位进行。xv6 的启动序列按如下方式启用保护模式和 32 位模式。</p><figure class="xv6-fig" id="fig-x86_seg"><img src="'+n+`" alt="保护模式下的段。" loading="lazy"><figcaption><span class="fig-no">图 B-2</span>保护模式下的段。</figcaption></figure><p>在保护模式下，段寄存器是<em>段描述符表</em>中的一个索引（见 <a class="figref" href="#fig-x86_seg">图 B-2</a>）。每个表项指定一个基物理地址、一个称为限长的最大虚拟地址，以及该段的权限位。这些权限就是保护模式中的保护：内核可以用它们确保程序只使用自己的内存。</p><p>xv6 几乎不使用段；它改用分页硬件，正如 <a href="./ch2">第 2 章</a> 所描述的。引导加载器建立段描述符表 <code>gdt</code> <span class="ln">(9182-9185)</span>，使所有段的基地址为零、限长为可能的最大值（4 GB）。该表有一个空表项、一个可执行代码表项和一个数据表项。代码段描述符设置了一个标志，表示代码应在 32 位模式下运行。有了这样的设置，当引导加载器进入保护模式时，逻辑地址就与物理地址一一对应。</p><p>引导加载器执行 <code>lgdt</code> 指令 <span class="ln">(9141)</span>，把处理器的全局描述符表（GDT）寄存器加载为值 <code>gdtdesc</code> <span class="ln">(9187-9189)</span>，它指向表 <code>gdt</code>。</p><p>加载 GDT 寄存器之后，引导加载器通过设置寄存器 <code>%cr0</code> 中的第 1 位（<code>CR0_PE</code>）来启用保护模式 <span class="ln">(9142-9144)</span>。启用保护模式不会立即改变处理器把逻辑地址转换为物理地址的方式；只有当你把新值加载到某个段寄存器时，处理器才会读取 GDT 并改变其内部分段设置。不能直接修改 <code>%cs</code>，因此代码改为执行一条 <code>ljmp</code>（远跳转）指令 <span class="ln">(9153)</span>，它允许指定一个代码段选择子。跳转在下一行继续执行 <span class="ln">(9156)</span>，但在此过程中把 <code>%cs</code> 设置为引用 <code>gdt</code> 中的代码描述符表项。该描述符描述的是一个 32 位代码段，因此处理器切换到 32 位模式。引导加载器就这样照料着处理器，走过了从 8088 经 80286 到 80386 的演进。</p><p>引导加载器在 32 位模式下的第一个动作是用 <code>SEG_KDATA</code> 初始化数据段寄存器 <span class="ln">(9158-9161)</span>。逻辑地址现在直接映射到物理地址。执行 C 代码之前剩下的唯一步骤，是在一块未使用的内存区域中建立栈。从 <code>0xa0000</code> 到 <code>0x100000</code> 的内存通常散布着设备内存区域，而 xv6 内核期望被放在 <code>0x100000</code>。引导加载器自身位于 <code>0x7c00</code> 到 <code>0x7e00</code>（512 字节）。基本上任何其他内存区域都可以作为栈的位置。引导加载器选择 <code>0x7c00</code>（在本文件中称为 <code>$start</code>）作为栈顶；栈将从那里向下朝 <code>0x0000</code> 增长，远离引导加载器。</p><p>最后，引导加载器调用 C 函数 <code>bootmain</code> <span class="ln">(9168)</span>。<code>Bootmain</code> 的任务是加载并运行内核。只有在出了问题时它才会返回。在这种情况下，代码在端口 <code>0x8a00</code> 上发送几个输出字。在真实硬件上，该端口没有连接设备，因此这段代码什么也不做。如果引导加载器运行在 PC 模拟器中，端口 <code>0x8a00</code> 与模拟器本身相连，可以把控制权转回模拟器。无论是否在模拟器中，代码随后都执行一个无限循环 <span class="ln">(9177-9178)</span>。真实的引导加载器可能会先尝试打印一条错误消息。</p><h2 id="appB-s2" tabindex="-1">代码：C 引导程序 <a class="header-anchor" href="#appB-s2" aria-label="Permalink to &quot;代码：C 引导程序 {#appB-s2}&quot;">​</a></h2><p>引导加载器的 C 部分 <code>bootmain.c</code> <span class="ln">(9200)</span> 期望在磁盘上从第二个扇区开始找到一份内核可执行文件的副本。内核是 ELF 格式的二进制，正如我们在 <a href="./ch2">第 2 章</a> 中看到的。为了访问 ELF 头部，<code>bootmain</code> 加载 ELF 二进制的前 4096 字节 <span class="ln">(9214)</span>。它把内存中的副本放在地址 <code>0x10000</code>。</p><p>下一步是快速检查这很可能是一个 ELF 二进制，而不是未初始化的磁盘。<code>Bootmain</code> 从 ELF 头部起始处之后 <code>off</code> 字节处的磁盘位置读取该段的内容，并写到从地址 <code>paddr</code> 开始的内存。<code>Bootmain</code> 调用 <code>readseg</code> 从磁盘加载数据 <span class="ln">(9238)</span>，并调用 <code>stosb</code> 把该段的剩余部分清零 <span class="ln">(9240)</span>。<code>Stosb</code> <span class="ln">(0492)</span> 使用 x86 指令 <code>rep</code> <code>stosb</code> 初始化一块内存的每个字节。</p><p>内核经过编译和链接，期望自己在从 <code>0x80100000</code> 开始的虚拟地址处。因此，函数调用指令必须提到形如 <code>0x801xxxxx</code> 的目标地址；你可以在 <code>kernel.asm</code> 中看到例子。这个地址在 <code>kernel.ld</code> <span class="ln">(9311)</span> 中配置。<code>0x80100000</code> 是一个相对较高的地址，接近 32 位地址空间的末端；<a href="./ch2">第 2 章</a> 解释了这个选择的原因。如此高的地址处可能根本没有物理内存。内核开始执行后，会设置分页硬件，把从 <code>0x80100000</code> 开始的虚拟地址映射到从 <code>0x00100000</code> 开始的物理地址；内核假定这个较低地址处有物理内存。然而在引导过程的这个时刻，分页尚未启用。取而代之的是，<code>kernel.ld</code> 指定 ELF 的 <code>paddr</code> 从 <code>0x00100000</code> 开始，这使引导加载器把内核复制到分页硬件最终将指向的低物理地址处。</p><p>引导加载器的最后一步是调用内核的入口点，即内核期望开始执行的那条指令。对 xv6 来说，入口地址是 <code>0x10000c</code>：</p><div class="listing"><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"># objdump </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f kernel</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kernel:     file format elf32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i386</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">architecture: i386, flags </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">00000112</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EXEC_P, HAS_SYMS, D_PAGED</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">start address </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0010000c</span></span></code></pre></div><p>按照约定，<code>_start</code> 符号指定 ELF 入口点，它在文件 <code>entry.S</code> <span class="ln">(1040)</span> 中定义。由于 xv6 尚未建立虚拟内存，xv6 的入口点就是 <code>entry</code> 的物理地址 <span class="ln">(1044)</span>。</p><h2 id="appB-s3" tabindex="-1">现实世界 <a class="header-anchor" href="#appB-s3" aria-label="Permalink to &quot;现实世界 {#appB-s3}&quot;">​</a></h2><p>本附录描述的引导加载器编译后约为 470 字节机器码，具体取决于编译 C 代码时使用的优化。为了装进这么小的空间，xv6 引导加载器做了一个重大的简化假设：内核已经被连续地写在引导磁盘上、从扇区 1 开始。更常见的情况是，内核存放在普通文件系统中，在那里它们可能并不连续，或者通过网络加载。这些复杂性要求引导加载器能够驱动各种磁盘和网络控制器，并理解各种文件系统和网络协议。换句话说，引导加载器本身必须是一个小型的操作系统。由于这样复杂的引导加载器肯定装不进 512 字节，大多数 PC 操作系统使用两步引导过程。首先，一个像本附录这样的简单引导加载器从已知的磁盘位置加载一个功能齐全的引导加载器，通常依靠受空间限制较小的 BIOS 进行磁盘访问，而不是试图自己驱动磁盘。然后，这个完整的加载器摆脱了 512 字节的限制，可以实现定位、加载和执行所需内核所需的复杂性。现代 PC 避免了许多上述复杂性，因为它们支持统一可扩展固件接口（UEFI），它允许 PC 从磁盘读取更大的引导加载器（并以保护模式和 32 位模式启动它）。</p><p>本附录的写法仿佛加电与引导加载器执行之间唯一发生的事情就是 BIOS 加载引导扇区。事实上，BIOS 做了大量初始化工作，以使现代计算机的复杂硬件看起来像一台传统的标准 PC。BIOS 实际上是一个嵌入硬件中的小型操作系统，在计算机启动之后仍然存在。</p><h2 id="appB-s4" tabindex="-1">练习 <a class="header-anchor" href="#appB-s4" aria-label="Permalink to &quot;练习 {#appB-s4}&quot;">​</a></h2><p><strong>练习 1.</strong> 由于扇区粒度，正文中对 <code>readseg</code> 的调用等价于 <code>readseg((uchar*)0x100000, 0xb500, 0x1000)</code>。实践中，这种草率的行为结果并不是问题。为什么草率的 readsect 不会造成问题？答案是代码/数据页不重叠以及虚拟地址/文件偏移对齐这两者的结合。</p><p><strong>练习 2.</strong> 假设你想让 bootmain() 把内核加载到 0x200000 而不是 0x100000，并且你通过修改 bootmain()、给每个 ELF 段的 va 加上 0x100000 来做到这一点。会出问题。是什么问题？</p><p><strong>练习 3.</strong> 引导加载器把 ELF 头部复制到内存中任意位置 <code>0x10000</code>，这似乎有潜在危险。为什么它不调用 <code>malloc</code> 来获得所需的内存？</p>`,32)])])}const k=s(p,[["render",i]]);export{g as __pageData,k as default};
